// laço do relay de uma outbox transacional
const rows = await db.query("SELECT * FROM outbox WHERE sent = false ORDER BY id");
for (const row of rows) {
  await broker.publish(row.event);                                   // 1
  // <- o relay cai aqui
  await db.query("UPDATE outbox SET sent = true WHERE id = $1", [row.id]); // 2
}

// relay loop of a transactional outbox
const rows = await db.query("SELECT * FROM outbox WHERE sent = false ORDER BY id");
for (const row of rows) {
  await broker.publish(row.event);                                   // 1
  // <- the relay crashes here
  await db.query("UPDATE outbox SET sent = true WHERE id = $1", [row.id]); // 2
}
